//   vacuous. In the rollback branch, RollbackConstrainedSuffix returns a
//   repaired constrained prefix that is parser-valid. In the narrow token-step
//   branch, ConstrainedStep returns EOS or a parser-valid next token; on the
//   non-EOS path, AppendConstrainedToken preserves validity. In the wide
//   symbol-progress branch, ConstrainedSymbolInGenerated returns currentOut that
//   is a valid parser prefix, so assigning it preserves the invariant.
// progress: The explicit-open branch consumes one token-step for the visible
//   opener and appends one token, so |generated| stays within
//   |generatedPrefix| + steps. The close branch consumes one token-step and
//   appends at most one visible delimiter. The rollback branch increments steps
//   by 1 while generated may shrink, so the bound is preserved. The narrow
//   token-step branch consumes one token-step and appends at most one visible
//   token. The wide symbol-progress branch consumes stepsUsed token-steps;
//   visible growth is at most the accepted valid prefix length, which is no
//   more than stepsUsed, so |generated| <= |generatedPrefix| + steps remains
//   true.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var narrowThreshold: nat := 10;
var rollbackLimit: nat := 48;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var openedGenerated, openedInside, openedCurrent := helpers.OpenConstrainedSpan(lm, generated);
    generated := openedGenerated;
    insideConstrainedOut := openedInside;
    currentConstrainedOut := openedCurrent;
    steps := steps + 1;
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
    break;
  } else {
    var deadEnd := helpers.DeadEndDetection(parser, currentConstrainedOut, 1);
    if deadEnd || |currentConstrainedOut| >= rollbackLimit {
      var rolledGenerated, rolledCurrent := helpers.RollbackConstrainedSuffix(
        parser, generated, currentConstrainedOut
      );
      generated := rolledGenerated;
      insideConstrainedOut := true;
      currentConstrainedOut := rolledCurrent;
      steps := steps + 1;
    } else {
      var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
      var constrainedPrompt := prompt + stablePrefix;
      var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);

      if validCount <= narrowThreshold {
        var next := helpers.ConstrainedStep(
          lm, parser, constrainedPrompt, currentConstrainedOut, eosToken
        );
        steps := steps + 1;
        if next == eosToken {
          break;
        } else {
          var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
            lm, parser, generated, currentConstrainedOut, next
          );
          generated := appendedGenerated;
          insideConstrainedOut := appendedInside;
          currentConstrainedOut := appendedCurrent;
        }
      } else {
        var remaining: nat := maxSteps - steps;
        var symbolBudget: nat := if stepTokenBudget == 0 || stepTokenBudget > remaining then remaining else stepTokenBudget;
        var symbolGenerated, symbolOut, hitEos, symbolSteps := helpers.ConstrainedSymbolInGenerated(
          lm, parser, constrainedPrompt, generated, currentConstrainedOut, symbolBudget, eosToken
        );
        generated := symbolGenerated;
        insideConstrainedOut := true;
        currentConstrainedOut := symbolOut;
        steps := steps + symbolSteps;
        if hitEos {
          break;
        }
      }
    }
  }
}

cost := steps;
